python3 -c "
import json,re
os_=json.load(open('/opt/trading-bot/positions_regr/orders.json'))
ps={p['order_id']:p for p in json.load(open('/opt/trading-bot/positions_regr/positions.json'))}
for o in os_:
    p=ps.get(o['id'])
    if p and p['id']>=231:
        print('#%d %s appr->t_in %.0fs  placed-appr %.0fs  rule %s setup %s'%(p['id'],p['sym'],(p['t_in']-o.get('approved_t',0))/1000,(o['placed_t']-o.get('approved_t',0))/1000,o['rule'],o.get('setup')))
rows=[]
for ln in open('/opt/trading-bot/positions_regr/chan.log',encoding='utf-8',errors='replace'):
    m=re.match(r'(\d\d-\d\d \d\d:\d\d:\d\d) cycle ([\d.]+)s (.*)',ln)
    if m and m.group(1)[:5]>='11-11': rows.append((m.group(1),float(m.group(2)),m.group(3)))
big=[r for r in rows if r[1]>30]
print('cycles since 11-11:',len(rows),'over 30s:',len(big),'max',max(r[1] for r in rows))
for r in big[-8:]: print(r[0],r[1],r[2][:140])
" | LC_ALL=C tr -cd '\11\12\40-\176'; echo ---LOOP; grep -n "sleep\|def loop" /opt/trading-bot/positions/chan_orders.py | tail -5
